#!/usr/bin/env python3
"""
patch-154 — 24-hour appointment reminders.

What ships:
  - Migration: reminded_at column on tenant_appointments + index for the
    "needs reminder" lookup (tenant_id, appointment_date, reminded_at).
  - Artisan command: appointments:remind
      * Loops active tenants, computes 23-25h window in tenant timezone.
      * Sends email + SMS via existing EmailService / SmsService.
      * Stamps reminded_at on every row visited (idempotence guard).
      * Failures logged but never retried (better to under-notify).
      * --dry-run + --tenant=ID flags for debugging.
  - Hourly scheduler entry in routes/console.php.
  - Email template: appointment_reminder (default; tenant can override
    via tenant_email_templates row).
  - SMS body inline ("Shop: Reminder, appointment tomorrow at...").
  - Settings panel: replaced placeholder "24-hour reminder · Coming soon"
    with WIRED "Appointment reminder" row. Defaults ON for both channels.
  - SettingsController validate + save the two new toggle keys.

Setup steps after deploy:
  - php artisan migrate --force
  - Verify cron is running schedule:run every minute on the droplet.
    (No new cron entry needed if it already runs schedule:run.)
  - Test with: php artisan appointments:remind --dry-run

Patch 155 will mirror this for deliveries. Patch 156 will add the
explicit "Save & Notify" buttons to the delivery drawer.

Standalone Python. Idempotent.
"""
